mapper.update:
CREATE SEQUENCE ${tableName}_SEQ START WITH 1  MAXVALUE 99999999 MINVALUE 1 CYCLE CACHE 20;
CREATE INDEX ${tableName}_IDX1 ON ${tableName}(STATUS, REQDATE);
CREATE INDEX ${tableName}_IDX2 ON ${tableName}(PHONE);
CREATE INDEX ${tableName}_IDX3 ON ${tableName}(RSLT, REQDATE);

UPDATE ${tableName}
SET
    STATUS = CASE WHEN STATUS = '3' THEN STATUS ELSE #{parameter.messageStatus} END,
    TERMINATEDDATE = NOW()
    , SENTDATE = TO_TIMESTAMP(#{parameter.sentDate}, 'YYYYMMDDHH24MISS')
    , RSLT = #{parameter.doneCode}
    , REPORTDATE = TO_TIMESTAMP(#{parameter.doneDate}, 'YYYYMMDDHH24MISS')
    , ROUTE_ID = #{parameter.routeId}
    , TELCOINFO = #{parameter.doneTelco}
    , FILE_CNT_REAL = #{parameter.realContentsCount}
WHERE
    MSGKEY IS NULL
    MSGKEY = CAST(#{parameter.key} AS numeric)
